import re

def predict(board_lines, action):
    """
    Predict next board for game bp35 level 2.
    """
    board = [list(row) for row in board_lines]

    def advance_bar(b):
        for c in range(64):
            if b[63][c] == 'W':
                b[63][c] = 'p'
                break

    def fill_rect(b, r0, r1, c0, c1, color):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if 0 <= r < 64 and 0 <= c < 64:
                    b[r][c] = color

    act = action.strip()
    up = act.upper()

    # --- RESET ---
    if up == 'RESET':
        advance_bar(board)
        return [''.join(r) for r in board]

    # --- MOUSE ---
    m = re.match(r'MOUSE\(row=(\d+),\s*col=(\d+)\)', act)
    if m:
        r, c = int(m.group(1)), int(m.group(2))
        if r == 63:
            advance_bar(board)
            return [''.join(row) for row in board]

        # Transition 1 & 11: MOUSE(33,21) or MOUSE(33,45) triggers multi-region repaint
        # Observed: rows 1-5 cols 13-35 become N with G borders (tile pattern)
        #           rows 7-18 cols 13-29: S -> tile pattern (B/p/Y/W)
        #           rows 24-27: become S
        if (r, c) in [(33, 21), (33, 45)]:
            # Fill rows 1-5, cols 13-35 with N (with G at borders)
            for rr in range(1, 6):
                for cc in range(13, 36):
                    if rr in (1, 5) or cc in (13, 17, 19, 23, 25, 29, 31, 35):
                        board[rr][cc] = 'G'
                    else:
                        board[rr][cc] = 'N'
            # Restore tile pattern in rows 7-18, cols 13-29 (remove S highlight)
            for rr in range(7, 19):
                for cc in range(13, 30):
                    if board[rr][cc] == 'S':
                        board[rr][cc] = 'B'
            # Fill rows 24-27, cols 13-29 and 37-53 with S
            fill_rect(board, 24, 27, 13, 29, 'S')
            fill_rect(board, 24, 27, 37, 53, 'S')

        # Transition 4/13: MOUSE(27,45) - fill rows 24-29, cols 43-47 with S
